corrected_code:
def get_workspace_documents(request, workspace_id):
    workspace = get_object_or_404(
        Workspace.objects.prefetch_related(
            Prefetch('confidential_files', queryset=ConfidentialFile.objects.all())
        ),
        id=workspace_id,
        members=request.user
    )
    files = [{'id': f.id, 'filename': f.filename, 'download_url': f.s3_url} for f in workspace.confidential_files.all()]
    return JsonResponse({'workspace': workspace.name, 'files': files})
